import UIKit

class StackedLayers: CAStackLayer {
    private var shouldPlaceIcons = true
    private var iconScale: CGFloat = 0.7
    private var icons: [CALayer] = []

    init(icons: [UIImage], iconScale: CGFloat = 0.7) {
        super.init()
        self.iconScale = iconScale
        self.icons = icons.map { imageLayer(for: image: $0) }
        self.addSublayer(self.icons.first!)
        self.addSublayer(self.icons.last!)
    }

    override func layoutSublayers() {
        super.layoutSublayers()
        if shouldPlaceIcons {
            placeIcons()
        } else {
            shouldPlaceIcons = true
        }
    }

    private func placeIcons() {
        shouldPlaceIcons = false
        let bounds = self.bounds
        let iconsSize = bounds.width * iconScale
        let iconsInset = bounds.width - iconsSize

        for (index, icon) in icons.enumerated() {
            icon.bounds = CGRect(x: 0, y: 0, width: iconsSize, height: iconsSize)
            icon.position = CGPoint(x: bounds.midX, y: bounds.midY)
