Here's a JavaScript implementation for packing and unpacking an array of entities into an ArrayBuffer. The entities have the fields `id` (4 bits) and `size` (3 bits).

```javascript
function packEntities(entities) {
  const buffer = new ArrayBuffer(entities.length);
  const view = new DataView(buffer);

  entities.forEach((entity, index) => {
    const id = entity.id;
    const size = entity.size;

    // Pack id (4 bits) and size (3 bits) into a single 7-bit value
    const combined = (id << 3) | size;

    // Write the combined value to the buffer
    view.setUint8(index, combined);

    // Write the remaining bits of the id (if any)
    if (id > 15) {
      view.setUint8(index + 1, id >> 3);
    }
  });

  return buffer;
}

function unpackEntities(buffer) {
  const entities = [];
  const view = new DataView(buffer);
  let index = 0;

  while (index < buffer.byteLength) {
    const combined = view.getUint8(index);
    const id = combined >> 3;
    const size = combined & 7;

    // If the id is spread across two bytes, read the second byte
    if (id > 15) {
      id |= view.getUint8(index + 1) << 3;
      index++;
    }

    entities.push({ id, size });
    index++;
  }

  return entities;
}
```

You can use these functions like this:

```javascript
const entities = [
  { id: 3, size: 2 },
  { id: 12, size: 5 },
  { id: 1, size: 1 }
];

const packedBuffer = packEntities(entities);
const unpackedEntities = unpackEntities(packedBuffer);

console.log(unpackedEntities); // [ { id: 3, size: 2 }, { id: 12, size: 5 }, { id: 1, size: 1 } ]
```

