First, let's define a base class for all MSL nodes:

```swift
protocol MSLNode {}
```

Next, let's create a few examples of MSL nodes:

```swift
struct Function: MSLNode {
    let name: String
    let parameters: [Parameter]
    let body: [Statement]
}

struct Parameter: MSLNode {
    let name: String
    let type: String
}

enum Statement: MSLNode {
    case declaration(VariableDeclaration)
    case expression(Expression)
    case functionCall(FunctionCall)
    case ifStatement(IfStatement)
    case loop(Loop)
    case returnStatement(ReturnStatement)
}

struct VariableDeclaration: MSLNode {
    let name: String
    let type: String
    let initializer: Expression?
}

struct Expression: MSLNode {
    // Define different types of expressions here
}

struct FunctionCall: MSLNode {
    let functionName: String
    let arguments: [Expression]
}

struct IfStatement: MSLNode {
    let condition: Expression
    let thenBranch: [Statement]
    let elseBranch: [Statement]?
}

struct Loop: MSLNode {
    let loopType: LoopType
    let condition: Expression
    let body: [Statement]
}

struct ReturnStatement: MSLNode {
    let expression: Expression?
}
```

In this example, we have defined a few basic MSL nodes, such as `Function`, `Parameter`, `Statement`, `VariableDeclaration`, `Expression`, `FunctionCall`, `IfStatement`, `Loop`, and `ReturnStatement`. Each node has a specific structure, and some nodes, like `Statement`, are enums that can represent multiple types of nodes.

