```typescript
function timeAgo(date: Date): string {
  const currentDate = new Date();
  const secondsPassed = Math.floor((currentDate.getTime() - date.getTime()) / 1000);

  const minutes = 60;
  const hours = 60 * minutes;
  const days = 24 * hours;
  const weeks = 7 * days;
  const months = 30 * days;
  const years = 365 * days;

  if (secondsPassed < minutes) {
    return `${secondsPassed} seconds ago`;
  }

  if (secondsPassed < hours) {
    return `${Math.floor(secondsPassed / 60)} minutes ago`;
  }

  if (secondsPassed < days) {
    return `${Math.floor(secondsPassed / 60 / 60)} hours ago`;
  }

  if (secondsPassed < weeks) {
    return `${Math.floor(secondsPassed / days)} days ago`;
  }

  if (secondsPassed < months) {
    return `${Math.floor(secondsPassed / days / 7)} weeks ago`;
  }

  if (secondsPassed < years) {
    return `${Math.floor(secondsPassed / days / 30)} months ago`;
  }

  return `${Math.floor(secondsPassed / days / 365)} years ago`;
}
```

